import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, 'data');

function isWithin(base, target) {
  const rel = path.relative(base, target);
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Path to a file relative to the data directory' }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { path: relPath } = args;
  if (typeof relPath !== 'string' || relPath.length === 0) {
    throw new Error('path is required');
  }
  const resolved = path.resolve(DATA_DIR, relPath);
  if (!isWithin(DATA_DIR, resolved)) {
    throw new Error('path must stay within the data directory');
  }
  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (e) {
    throw new Error(`File not found: ${relPath}`);
  }
  if (!stat.isFile()) {
    throw new Error('path must point to a file');
  }
  const rel = path.relative(DATA_DIR, resolved);
  const ext = path.extname(resolved).toLowerCase();
  const text = `relative path: ${rel}\nbyte size: ${stat.size}\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
